/* All records below are generated sample data. No backend requests occur. */
const scaleApps=['payments','identity','orders','billing','risk','search','shipping','support','analytics','platform','inventory','customer'];
const scaleRegions=['us-east-1','us-west-2','eu-west-1'];
const scaleTeams=['Payments','Security','Commerce','Finance','Risk','Discovery','Logistics','Support','Data','Platform','Supply','Experience'];
const scaleVpcs=scaleRegions.flatMap((region,r)=>scaleApps.map((app,a)=>({id:`vpc-${region}-${app}`,name:`${app}-prod`,region,app,appIndex:a,index:r*12+a,policyReplicas:3,enforcementNodes:12,integrationNodes:4})));
const ruleKinds=[{name:'Change approval',operation:'change.execute',resource:'Production changes',condition:'Require two approvals before the change starts.'},{name:'Access window',operation:'access.elevate',resource:'Access requests',condition:'Require an approved access window.'},{name:'Release checks',operation:'release.publish',resource:'Release artifacts',condition:'Require successful build and security checks.'},{name:'Data export',operation:'data.export',resource:'Data export requests',condition:'Require an approved export destination.'},{name:'Service identity',operation:'service.connect',resource:'Service connections',condition:'Require a valid service identity.'},{name:'Remediation check',operation:'remediation.complete',resource:'Remediation records',condition:'Require current verification data.'},{name:'Deployment window',operation:'deployment.start',resource:'Deployment requests',condition:'Require an approved deployment window.'},{name:'Secret access',operation:'secret.read',resource:'Secret read requests',condition:'Require the assigned workload identity.'}];
const scalePolicies=Array.from({length:4800},(_,i)=>{const a=i%12,k=ruleKinds[Math.floor(i/12)%8],revision=2+i%23;return {id:`POL-${String(i+1).padStart(5,'0')}`,name:`${k.name} / ${scaleApps[a]} / ${String(Math.floor(i/96)+1).padStart(2,'0')}`,app:scaleApps[a],appIndex:a,team:scaleTeams[a],operation:k.operation,resource:k.resource,condition:k.condition,revision,behind:i%97===0,vpcs:scaleVpcs.filter(v=>v.appIndex===a).map(v=>v.id),segment:`group-${String(Math.floor(i/96)+1).padStart(2,'0')}`}});
const integrationTypes=[['servicenow','ServiceNow','Read change requirements and validation results.','Source readable',2],['github','GitHub','Read branch requirements and review results.','Source readable',1],['aws','AWS IAM','Read access rules for AWS resources.','Source readable',0],['okta','Okta','Read sign-in rules and group membership.','Access denied',0],['entra','Microsoft Entra ID','Read access conditions for user identities.','Source readable',0],['jira','Jira','Read issue workflow requirements.','Needs setup',0],['gitlab','GitLab','Read merge requirements and pipeline results.','Source readable',0],['kubernetes','Kubernetes','Read admission rules for workloads.','Node offline',0],['vault','HashiCorp Vault','Read secret access rules.','Source readable',0],['datadog','Datadog','Read monitor states for policy input.','Source readable',0],['pagerduty','PagerDuty','Read incident states and responder identities.','Source readable',0],['terraform','Terraform Cloud','Read workspace rules and run results.','Source readable',0]].map((x,i)=>({id:x[0],name:x[1],purpose:x[2],status:x[3],externalCount:x[4],vpcs:[scaleVpcs[i].id,scaleVpcs[12+i].id,scaleVpcs[24+i].id],owner:scaleTeams[i]}));
let scaleState={query:'',region:'',vpc:'',team:'',operation:'',delivery:'',page:1,size:25,sort:'id',selected:new Set()},fleetState={region:'',attention:false},integrationQuery='';
let savedPolicyViews=[];try{savedPolicyViews=JSON.parse(localStorage.getItem('ipe-policy-views-v1'))||[]}catch{}
const sfmt=n=>n.toLocaleString('en-US');
function scopeVpcs(p){return p.vpcs.map(id=>scaleVpcs.find(v=>v.id===id))}
function scaleMatches(){const s=scaleState,q=s.query.toLowerCase();return scalePolicies.filter(p=>(!q||`${p.id} ${p.name} ${p.operation} ${p.resource} ${p.team} ${p.segment}`.toLowerCase().includes(q))&&(!s.team||p.team===s.team)&&(!s.operation||p.operation===s.operation)&&(!s.delivery||(s.delivery==='behind'?p.behind:!p.behind))&&(!s.vpc||p.vpcs.includes(s.vpc))&&(!s.region||scopeVpcs(p).some(v=>v.region===s.region))).sort((a,b)=>s.sort==='name'?a.name.localeCompare(b.name):s.sort==='behind'?Number(b.behind)-Number(a.behind)||a.id.localeCompare(b.id):a.id.localeCompare(b.id))}
function vpcPending(v){return scalePolicies.filter(p=>p.behind&&p.appIndex===v.appIndex&&v.region===scaleRegions[0]).length}
function selectFilter(label,key,values,selected){return `<label class="scale-filter"><span>${label}</span><select data-scale-filter="${key}"><option value="">All ${label==='VPCs'?'VPCs':label.toLowerCase()}</option>${values.map(x=>{const value=typeof x==='string'?x:x.value,text=typeof x==='string'?x:x.label;return `<option value="${esc(value)}" ${selected===value?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`}
function scalePolicyRows(rows){return rows.map(p=>`<tr><td><input type="checkbox" data-scale-select="${p.id}" aria-label="Select ${p.id}" ${scaleState.selected.has(p.id)?'checked':''}></td><td><button class="record-link" data-scale-policy="${p.id}">${p.name}</button><span class="sub mono">${p.id} · ${p.team}</span></td><td><span class="mono">${p.operation}</span><span class="sub">${p.resource} · ${p.app} · ${p.segment}</span></td><td><button class="scale-link" data-scale-policy="${p.id}" data-targets="true">3 VPCs · 6 clusters</button><span class="sub">36 enforcement nodes</span></td><td><span class="mono">r${p.revision}</span><span class="sub">${p.behind?`35 / 36 nodes use r${p.revision}`:'36 / 36 nodes use this revision'}</span></td><td>${badge(p.behind?'1 node behind':'All nodes current',p.behind?'warn':'good')}</td></tr>`).join('')}
function scalePolicyScreen(){const all=scaleMatches(),pages=Math.max(1,Math.ceil(all.length/scaleState.size));scaleState.page=Math.min(scaleState.page,pages);const offset=(scaleState.page-1)*scaleState.size,rows=all.slice(offset,offset+scaleState.size),selectedOnPage=rows.length&&rows.every(p=>scaleState.selected.has(p.id));return `${head('Policy enforcement','Find a policy by request scope, owner, or deployment location.',`<button class="btn" data-scale-export>Export matches</button>`)}<div class="scale-countline"><strong>${sfmt(scalePolicies.length)} active policies</strong><span>36 VPCs</span><span>72 enforcement clusters</span><span>${scalePolicies.filter(p=>p.behind).length} policies have a node behind</span></div><div class="scale-views" aria-label="Policy views"><button data-policy-view="all" class="${!scaleState.delivery&&!scaleState.team?'active':''}">All active policies</button><button data-policy-view="behind" class="${scaleState.delivery==='behind'?'active':''}">Nodes behind</button><button data-policy-view="platform" class="${scaleState.team==='Platform'?'active':''}">Platform team</button>${savedPolicyViews.map((v,i)=>`<button data-saved-view="${i}">${esc(v.name)}</button>`).join('')}<button data-save-policy-view>Save this view</button></div><section class="panel"><div class="scale-search-row"><label class="scale-search">${icon('search')}<input id="scale-policy-search" placeholder="Search policy ID, action, resource, or owner" aria-label="Search policies" value="${esc(scaleState.query)}"></label><label class="scale-sort">Sort <select data-scale-sort><option value="id" ${scaleState.sort==='id'?'selected':''}>Policy ID</option><option value="name" ${scaleState.sort==='name'?'selected':''}>Policy name</option><option value="behind" ${scaleState.sort==='behind'?'selected':''}>Nodes behind first</option></select></label></div><div class="scale-filters">${selectFilter('Regions','region',scaleRegions,scaleState.region)}${selectFilter('VPCs','vpc',scaleVpcs.filter(v=>!scaleState.region||v.region===scaleState.region).map(v=>({value:v.id,label:v.region+' / '+v.name})),scaleState.vpc)}${selectFilter('Owners','team',scaleTeams,scaleState.team)}${selectFilter('Actions','operation',ruleKinds.map(k=>k.operation),scaleState.operation)}${selectFilter('Node states','delivery',[{value:'behind',label:'At least one node behind'},{value:'current',label:'All assigned nodes current'}],scaleState.delivery)}<button class="btn quiet" data-clear-policy-filters>Clear filters</button></div><div class="scale-selection"><span>${sfmt(all.length)} matching policies${scaleState.selected.size?` · ${scaleState.selected.size} selected, including hidden rows`:''}</span><div>${scaleState.selected.size?'<button class="btn small" data-review-policy-selection>Review selected policies</button><button class="btn quiet small" data-clear-selection>Clear selection</button>':'<span>Select rows to review their deployment scope.</span>'}</div></div><div class="table-wrap"><table class="scale-policy-table"><thead><tr><th><input type="checkbox" data-scale-page-select aria-label="Select this page" ${selectedOnPage?'checked':''}></th><th>Policy / owner</th><th>Requests that match</th><th>Assigned locations</th><th>Assigned revision</th><th>Node reports</th></tr></thead><tbody>${scalePolicyRows(rows)}</tbody></table>${rows.length?'':'<div class="empty">No policies match these filters. Change a filter or clear all filters.</div>'}</div><div class="scale-pagination"><span>${all.length?offset+1:0}–${Math.min(offset+scaleState.size,all.length)} of ${sfmt(all.length)}</span><label>Rows <select data-scale-size>${[25,50,100].map(n=>`<option ${n===scaleState.size?'selected':''}>${n}</option>`).join('')}</select></label><div><button class="btn small" data-scale-page="${scaleState.page-1}" ${scaleState.page===1?'disabled':''}>Previous</button><span>Page ${scaleState.page} of ${pages}</span><button class="btn small" data-scale-page="${scaleState.page+1}" ${scaleState.page===pages?'disabled':''}>Next</button></div></div></section>`}
function showScalePolicy(id){const p=scalePolicies.find(x=>x.id===id);if(!p)return;modal(p.name,`${p.id} · Active policy · Owner: ${p.team}`,`<div class="scale-detail-callout"><h3>Requests that match</h3><p>${p.resource} for ${p.app} in production.</p><div class="scale-expression mono">action = ${p.operation}<br>application = ${p.app}<br>resource group = ${p.segment}<br>environment = production</div><h3>Required condition</h3><p>${p.condition}</p></div><div class="ops-section-label"><h2>Assigned locations</h2><span>Assigned revision: r${p.revision}</span></div><div class="table-wrap"><table><thead><tr><th>VPC / region</th><th>Clusters</th><th>Nodes current</th></tr></thead><tbody>${scopeVpcs(p).map((v,i)=>`<tr><td><a class="scale-link" href="#workspace/map/${v.id}">${v.name}</a><span class="sub">${v.region}</span></td><td>enforce-a, enforce-b</td><td>${i===0&&p.behind?'11 / 12':'12 / 12'}</td></tr>`).join('')}</tbody></table></div>${p.behind?`<div class="scale-detail-callout"><h3>Node behind</h3><p>${p.app}-prod / enforce-a / node-06 reports r${p.revision-1}.</p><p>The assigned revision is r${p.revision}. The last report was 12 minutes ago.</p></div>`:''}`,btn('Close','close'),true)}
function scaleClusterRows(v){return `<div class="table-wrap"><table><thead><tr><th>Cluster</th><th>Role</th><th>Nodes connected</th><th>Policy or source state</th></tr></thead><tbody>${[['enforce-a','Enforcement',6],['enforce-b','Enforcement',6],['integrate','Integration',4]].map(([id,role,n])=>`<tr><td><button class="record-link" data-scale-cluster="${id}" data-vpc="${v.id}">${v.name}-${id}</button></td><td>${role}</td><td>${v.index===7&&id==='integrate'?'3 / 4':`${n} / ${n}`}</td><td>${id==='enforce-a'&&vpcPending(v)?badge(`${vpcPending(v)} revisions waiting`,'warn'):id==='integrate'?integrationTypes[v.appIndex].name:badge('All revisions current','good')}</td></tr>`).join('')}</tbody></table></div>`}
function scaleFleetScreen(){const id=location.hash.slice(1).split('/')[2],v=scaleVpcs.find(x=>x.id===id);if(v)return scaleVpcDetail(v);const rows=scaleVpcs.filter(v=>(!fleetState.region||v.region===fleetState.region)&&(!fleetState.attention||vpcPending(v)>0||v.index===7));return `${head('Service map','Open a virtual private cloud (VPC) to inspect its service layer and node clusters.')}<div class="scale-countline"><strong>36 VPCs</strong><span>108 policy service replicas</span><span>432 enforcement nodes</span><span>144 integration nodes</span></div><div class="fleet-toolbar"><label>Region <select data-fleet-region><option value="">All regions</option>${scaleRegions.map(r=>`<option ${fleetState.region===r?'selected':''}>${r}</option>`).join('')}</select></label><label class="scale-checkbox"><input type="checkbox" data-fleet-attention ${fleetState.attention?'checked':''}>Show VPCs that need attention</label><span>${rows.length} VPCs shown</span></div>${scaleRegions.filter(r=>!fleetState.region||fleetState.region===r).map(r=>`<section class="fleet-region"><div class="ops-section-label"><h2>${r}</h2><span>${rows.filter(v=>v.region===r).length} VPCs shown</span></div><div class="vpc-grid">${rows.filter(v=>v.region===r).map(v=>`<a class="vpc-card" href="#workspace/map/${v.id}"><div><strong>${v.name}</strong>${icon('arrow')}</div><span class="vpc-status">${vpcPending(v)?badge(`${vpcPending(v)} revisions waiting`,'warn'):v.index===7?badge('1 integration node offline','bad'):badge('All nodes current','good')}</span><dl><div><dt>Policy service layer</dt><dd>3 / 3 replicas</dd></div><div><dt>Enforcement</dt><dd>2 clusters · 12 nodes</dd></div><div><dt>Integration</dt><dd>1 cluster · 4 nodes</dd></div></dl><small>400 assigned policies</small></a>`).join('')||'<p class="muted">No VPCs match this filter.</p>'}</div></section>`).join('')}`}
function scaleVpcDetail(v){return `<a class="external-back" href="#workspace/map">${icon('back')} All VPCs</a>${head(v.name,`${v.region} · Production`, `<button class="btn" data-vpc-policies="${v.id}">View 400 assigned policies</button>`)}<div class="vpc-hierarchy"><div class="vpc-admin"><span>Central admin service</span><small>Assigns policy data to each VPC.</small></div><div class="vpc-path" aria-hidden="true">↓</div><section class="vpc-boundary"><div class="vpc-boundary-title"><strong>${v.id}</strong><span>VPC boundary</span></div><div class="vpc-layer"><div><h2>Policy service layer</h2><p>Stores assigned revisions and serves local nodes.</p></div><div class="replica-group">${[1,2,3].map(n=>`<button data-service-replica="${n}" data-vpc="${v.id}"><i></i>policy-${n.toString().padStart(2,'0')}</button>`).join('')}</div></div><div class="vpc-path" aria-hidden="true">↓</div><div class="vpc-clusters">${[['enforce-a','Enforcement cluster A','6 nodes','Evaluates requests with local policy data.'],['enforce-b','Enforcement cluster B','6 nodes','Evaluates requests with local policy data.'],['integrate','Integration cluster','4 nodes','Reads sources and publishes permitted data.']].map(([id,title,n,desc])=>`<button class="cluster-card" data-scale-cluster="${id}" data-vpc="${v.id}"><h3>${title}</h3><strong>${n}</strong><p>${desc}</p><span>Inspect nodes ${icon('arrow')}</span></button>`).join('')}</div></section></div><div class="ops-section-label"><h2>Clusters in this VPC</h2><span>Each node pulls the data that it needs.</span></div>${panel('Node groups',scaleClusterRows(v))}`}
function showCluster(vpc,id){const v=scaleVpcs.find(x=>x.id===vpc),integration=id==='integrate',n=integration?4:6;modal(`${v.name}-${id}`,`${v.region} · ${integration?'Integration':'Enforcement'} cluster`,`<div class="table-wrap"><table><thead><tr><th>Node</th><th>Connection</th><th>${integration?'Source connection':'Policy revisions'}</th><th>Last report</th></tr></thead><tbody>${Array.from({length:n},(_,i)=>{const offline=integration&&v.index===7&&i===3,behind=!integration&&id==='enforce-a'&&i===5&&vpcPending(v);return `<tr><td><button class="record-link" data-scale-node="${i+1}" data-cluster="${id}" data-vpc="${v.id}">node-${String(i+1).padStart(2,'0')}</button></td><td>${badge(offline?'Offline':'Connected',offline?'bad':'good')}</td><td>${integration?integrationTypes[v.appIndex].name:behind?`${vpcPending(v)} revisions waiting`:'400 / 400 current'}</td><td>${offline?'18 min ago':behind?'12 min ago':'20 sec ago'}</td></tr>`}).join('')}</tbody></table></div>`,btn('Close','close'),true)}
function scaleIntegrationScreen(){const rows=integrationTypes.filter(i=>`${i.name} ${i.purpose} ${i.owner} ${i.status}`.toLowerCase().includes(integrationQuery.toLowerCase()));return `${head('Integrations','Manage source access, node placement, and external policy discovery.')}<div class="scale-countline"><strong>12 integration types</strong><span>36 VPC deployments</span><span>3 integration types need attention</span><span>3 external policies in the sample</span></div><section class="panel"><div class="panel-head"><h2>Source connections</h2><label class="scale-search">${icon('search')}<input id="scale-integration-search" value="${esc(integrationQuery)}" placeholder="Search source, purpose, owner, or state" aria-label="Search integrations"></label></div><div class="table-wrap"><table class="scale-integration-table"><thead><tr><th>Integration / purpose</th><th>Owner</th><th>Deployment</th><th>Connection check</th><th>External policies</th><th>Next action</th></tr></thead><tbody>${rows.map(i=>`<tr><td><button class="record-link" data-scale-integration="${i.id}">${i.name}</button><span class="sub">${i.purpose}</span></td><td>${i.owner}</td><td>3 VPCs<span class="sub">3 clusters · 12 nodes</span></td><td>${badge(i.status,i.status==='Source readable'?'good':i.status==='Needs setup'?'blue':'warn')}</td><td>${i.externalCount?`${i.externalCount} discovered`:'No policy sample'}<span class="sub">${i.id==='servicenow'?'1 unknown condition · 1 expired observation':i.id==='github'?'Observed 1 min ago':'Discovery data is not included'}</span></td><td><button class="scale-link" data-scale-integration="${i.id}">${i.status==='Access denied'?'Check source access':i.status==='Needs setup'?'Complete setup':i.status==='Node offline'?'Inspect offline node':i.externalCount?'Inspect external policies':'Inspect connection'}</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No integrations match this search.</div>'}</div></section><div class="ops-section-label"><h2>External policies</h2>${link('View all external policies','contracts','quiet small')}</div>${panel('Requirements from connected systems',externalPolicyTable())}`}
function showScaleIntegration(id){const i=integrationTypes.find(x=>x.id===id);modal(i.name,i.purpose,`<div class="scale-detail-callout"><h3>Connection check</h3>${badge(i.status,i.status==='Source readable'?'good':'warn')}<p>${i.status==='Access denied'?'The source rejected the service identity. Check its access rights.':i.status==='Needs setup'?'The connection has no approved source identity. Complete source setup.':i.status==='Node offline'?'One integration node has not sent a report for 18 minutes. Inspect that node.':'The sample connection can read its assigned source scope.'}</p></div><div class="ops-section-label"><h2>VPC deployments</h2></div><div class="table-wrap"><table><thead><tr><th>VPC</th><th>Region</th><th>Cluster</th></tr></thead><tbody>${i.vpcs.map(id=>{const v=scaleVpcs.find(x=>x.id===id);return `<tr><td><a class="scale-link" href="#workspace/map/${id}">${v.name}</a></td><td>${v.region}</td><td><button class="scale-link" data-scale-cluster="integrate" data-vpc="${id}">4 integration nodes</button></td></tr>`}).join('')}</tbody></table></div><div class="scale-detail-callout"><h3>External policies</h3><p>${i.externalCount?`${i.externalCount} external policies are available in this sample.`:'External policy discovery is not included for this source in the sample.'}</p>${i.externalCount?`<button class="btn" data-source-policies="${i.id}">View external policies</button>`:''}</div>`,btn('Close','close'),true)}
function scaleOverview(){const waiting=scalePolicies.filter(p=>p.behind);return `${head('Operations overview','Check policy delivery, VPC health, and source access.')}<div class="ops-metrics">${[['Active policies','4,800','policies'],['VPCs','36','map'],['Runtime nodes','576','fleet'],['Integration types','12','integrations']].map(([l,v,s])=>`<a href="#workspace/${s}"><span>${l}</span><strong>${v}</strong>${icon('arrow')}</a>`).join('')}</div><div class="ops-overview-grid"><section class="panel"><div class="panel-head"><h2>Policies with nodes behind</h2><button class="btn quiet small" data-policy-view="behind">View all ${waiting.length}</button></div><div class="table-wrap"><table><thead><tr><th></th><th>Policy / owner</th><th>Requests that match</th><th>Assigned locations</th><th>Assigned revision</th><th>Node reports</th></tr></thead><tbody>${scalePolicyRows(waiting.slice(0,5))}</tbody></table></div></section><aside class="panel ops-attention"><div class="panel-head"><h2>Actions required</h2></div><a href="#workspace/map"><span class="ops-severity">Policy delivery</span><strong>${waiting.length} policy revisions have not reached all nodes</strong><small>Inspect the VPCs in us-east-1.</small>${icon('arrow')}</a><button data-scale-integration="okta"><span class="ops-severity">Source access</span><strong>Okta rejected the service identity</strong><small>Check the identity and its access rights.</small>${icon('arrow')}</button><button data-scale-integration="kubernetes"><span class="ops-severity">Node connection</span><strong>One integration node is offline</strong><small>Last report: 18 minutes ago.</small>${icon('arrow')}</button><button data-action="contract" data-id="closure"><span class="ops-severity">External policy</span><strong>A ServiceNow script is unknown</strong><small>Inspect the source requirements.</small>${icon('arrow')}</button></aside></div>`}
function scaleEndpointScreen(){return `${head('Endpoint registry','Open a VPC to inspect its policy service replicas and runtime nodes.')}<div class="scale-countline"><strong>684 registered service processes</strong><span>108 policy service replicas</span><span>432 enforcement nodes</span><span>144 integration nodes</span></div>${panel('Endpoints by VPC',`<div class="table-wrap"><table><thead><tr><th>VPC</th><th>Region</th><th>Policy service</th><th>Enforcement</th><th>Integration</th><th>Reports</th></tr></thead><tbody>${scaleVpcs.map(v=>`<tr><td><a class="scale-link" href="#workspace/map/${v.id}">${v.name}</a></td><td>${v.region}</td><td>3 replicas</td><td>2 clusters · 12 nodes</td><td>1 cluster · 4 nodes</td><td>${badge(v.index===7?'1 node offline':'All nodes connected',v.index===7?'warn':'good')}</td></tr>`).join('')}</tbody></table></div>`)}`}
function scaleTelemetryScreen(){return `${head('Telemetry','Check metric collection and trace delivery for each VPC.')}<div class="ops-metrics">${[['Policy service processes','108'],['Enforcement nodes','432'],['Integration nodes','144'],['Nodes without recent data','1']].map(([l,n])=>`<a href="#workspace/fleet"><span>${l}</span><strong>${n}</strong>${icon('arrow')}</a>`).join('')}</div>${panel('Telemetry by region',`<div class="table-wrap"><table><thead><tr><th>Region</th><th>VPCs</th><th>Metrics received</th><th>Trace test received</th><th>Next action</th></tr></thead><tbody>${scaleRegions.map((r,i)=>`<tr><td>${r}</td><td>12</td><td>${i===0?'227 / 228':'228 / 228'} processes</td><td>${i===0?'227 / 228':'228 / 228'} processes</td><td><a class="scale-link" href="#workspace/map">Inspect VPCs</a></td></tr>`).join('')}</tbody></table></div>`)}<p class="external-footnote">Metrics and trace tests indicate data arrival. They do not prove that a policy decision was correct.</p>`}
function scaleRolloutScreen(){return `${head('Policy delivery','Compare assigned revisions with the revisions that nodes report.')}<div class="scale-countline"><strong>${scalePolicies.filter(p=>p.behind).length} policies waiting</strong><span>All policies remain active on their assigned nodes.</span></div>${panel('Revisions waiting for node reports',`<div class="table-wrap"><table><thead><tr><th></th><th>Policy / owner</th><th>Requests that match</th><th>Assigned locations</th><th>Assigned revision</th><th>Node reports</th></tr></thead><tbody>${scalePolicyRows(scalePolicies.filter(p=>p.behind))}</tbody></table></div>`)}<p class="external-footnote">A node can run an older revision while it waits for the assigned revision.</p>`}
function scaleRender(){render()}
function scaleResetFilters(){Object.assign(scaleState,{query:'',region:'',vpc:'',team:'',operation:'',delivery:'',page:1})}
function applyPolicyView(name){scaleResetFilters();if(name==='behind')scaleState.delivery='behind';if(name==='platform')scaleState.team='Platform';if(location.hash!=='#workspace/policies')location.hash='#workspace/policies';else render()}
function policyCsv(rows){const fields=['Policy ID','Name','Owner','Action','Resource','Resource group','VPCs','Assigned revision','Nodes current'];const csv=[fields,...rows.map(p=>[p.id,p.name,p.team,p.operation,p.resource,p.segment,p.vpcs.join(' | '),'r'+p.revision,p.behind?'35/36':'36/36'])].map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='sample-policy-matches.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.scalePolicy){showScalePolicy(d.scalePolicy)}if(d.scalePage){scaleState.page=Number(d.scalePage);render()}if(d.policyView){applyPolicyView(d.policyView)}if(d.savedView!==undefined){const s=savedPolicyViews[Number(d.savedView)];Object.assign(scaleState,s.filters,{page:1});render()}if(d.savePolicyView!==undefined){modal('Save policy view','This view is stored in this browser.',`<label class="form-label" for="policy-view-name">View name</label><input class="form-input" id="policy-view-name" maxlength="60" placeholder="For example: Payments nodes behind">`,btn('Cancel','close')+'<button class="btn primary" data-confirm-policy-view>Save view</button>')}if(d.confirmPolicyView!==undefined){const name=$('#policy-view-name').value.trim();if(!name){$('#policy-view-name').focus();return}const {query,region,vpc,team,operation,delivery,sort}=scaleState;savedPolicyViews.push({name,filters:{query,region,vpc,team,operation,delivery,sort}});localStorage.setItem('ipe-policy-views-v1',JSON.stringify(savedPolicyViews));close();render()}if(d.clearPolicyFilters!==undefined){scaleResetFilters();render()}if(d.clearSelection!==undefined){scaleState.selected.clear();render()}if(d.reviewPolicySelection!==undefined){const rows=scalePolicies.filter(p=>scaleState.selected.has(p.id));const vpcs=new Set(rows.flatMap(p=>p.vpcs));modal('Review selected policies',`${rows.length} selected policies · ${vpcs.size} VPCs`,`<p>These policies affect ${vpcs.size*12} enforcement nodes.</p><p>${rows.filter(p=>p.behind).length} selected policies have a node behind.</p><div class="scale-detail-callout">This review does not change assignments. Export the selection to inspect its full scope.</div>`,btn('Close','close')+'<button class="btn primary" data-export-selection>Export selected policies</button>')}if(d.scaleExport!==undefined)policyCsv(scaleMatches());if(d.exportSelection!==undefined)policyCsv(scalePolicies.filter(p=>scaleState.selected.has(p.id)));if(d.scaleCluster)showCluster(d.vpc,d.scaleCluster);if(d.serviceReplica){const v=scaleVpcs.find(x=>x.id===d.vpc);modal(`policy-${String(d.serviceReplica).padStart(2,'0')}`,`${v.name} · ${v.region}`,`<div class="scale-detail-callout"><h3>Policy service replica</h3><p>Connection: connected.</p><p>Assigned policies: 400.</p><p>Last report: 20 seconds ago.</p><p>This replica serves policy data to local enforcement and integration clusters.</p></div>`,btn('Close','close'),true)}if(d.scaleNode){const v=scaleVpcs.find(x=>x.id===d.vpc),n=Number(d.scaleNode),offline=d.cluster==='integrate'&&v.index===7&&n===4;modal(`${v.name}-${d.cluster} / node-${String(n).padStart(2,'0')}`,`${v.region} · ${d.cluster==='integrate'?'Integration':'Enforcement'} node`,`<div class="scale-detail-callout"><h3>Node report</h3><p>Connection: ${offline?'offline':'connected'}.</p><p>Last report: ${offline?'18 minutes ago':d.cluster==='enforce-a'&&n===6&&vpcPending(v)?'12 minutes ago':'20 seconds ago'}.</p><p>${d.cluster==='integrate'?`Source connection: ${integrationTypes[v.appIndex].name}.`:`Assigned policies: 400. ${d.cluster==='enforce-a'&&n===6&&vpcPending(v)?vpcPending(v)+' revisions are waiting.':'All assigned revisions are active.'}`}</p></div>`,btn('Close','close'),true)}if(d.vpcPolicies){scaleResetFilters();scaleState.vpc=d.vpcPolicies;location.hash='#workspace/policies'}if(d.scaleIntegration)showScaleIntegration(d.scaleIntegration);if(d.sourcePolicies){close();filter=d.sourcePolicies==='servicenow'?'ServiceNow':'GitHub';location.hash='#workspace/contracts';setTimeout(()=>{filter=d.sourcePolicies==='servicenow'?'ServiceNow':'GitHub';render()},0)}});
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.scaleFilter){scaleState[d.scaleFilter]=e.target.value;if(d.scaleFilter==='region')scaleState.vpc='';scaleState.page=1;render()}if(d.scaleSort!==undefined){scaleState.sort=e.target.value;scaleState.page=1;render()}if(d.scaleSize!==undefined){scaleState.size=Number(e.target.value);scaleState.page=1;render()}if(d.scaleSelect){if(e.target.checked)scaleState.selected.add(d.scaleSelect);else scaleState.selected.delete(d.scaleSelect);render()}if(d.scalePageSelect!==undefined){const all=scaleMatches(),rows=all.slice((scaleState.page-1)*scaleState.size,scaleState.page*scaleState.size);rows.forEach(p=>e.target.checked?scaleState.selected.add(p.id):scaleState.selected.delete(p.id));render()}if(d.fleetRegion!==undefined){fleetState.region=e.target.value;render()}if(d.fleetAttention!==undefined){fleetState.attention=e.target.checked;render()}});
document.addEventListener('input',e=>{if(!['scale-policy-search','scale-integration-search'].includes(e.target.id))return;const id=e.target.id,pos=e.target.selectionStart,value=e.target.value;if(id==='scale-policy-search'){scaleState.query=value;scaleState.page=1}else integrationQuery=value;render();const input=document.getElementById(id);input.focus();input.setSelectionRange(pos,pos)});
document.addEventListener('click',e=>{if(!e.target.closest('[data-scale-about]'))return;modal('About this mock','All records are sample data.',`<div class="scale-detail-callout"><h3>Sample service mesh</h3><p>The mesh contains 36 VPCs in three regions.</p><p>Each VPC contains three policy service replicas, two enforcement clusters, and one integration cluster.</p><p>The policy list contains 4,800 active sample policies. Each policy has assignments in three VPCs.</p><h3>Local controls</h3><p>Search, filters, page selection, and exports use generated data in this browser.</p><p>Saved views remain in this browser. This mock does not test backend performance.</p><h3>Writing rule</h3><p>The project uses ASD-STE100 writing guidance. Required technical terms keep their defined meanings.</p><p>Full compliance requires a review of the standard and its dictionary.</p></div>`,btn('Close','close'))});
